    {
      "point": "Britannica text is repetitive and lacks substantive content, while Wikipedia provides detailed methods for cell counting.",
      "quote_britannica": "We have used the same method to calculate the number of cells that are used to generate a single cell size.",
      "quote_wikipedia": "Cell counting is any of various methods for the counting or similar quantification of cells in the life sciences, including medical diagnosis and treatment."
    }
  ],
  "claims": [],
  "term_pairs": [],
  "wiki_only_topics": [
    {
      "topic": "Counting chambers and hemocytometers",
      "quote_wikipedia": "A counting chamber, is a microscope slide that is especially designed to enable cell counting. Hemocytometers and Sedgewick Rafter counting chambers are two types of counting chambers."
    },
    {
      "topic": "Colony forming units and plating",
      "quote_wikipedia": "To quantify the number of cells in a culture, the cells can be simply plated on a petri dish with growth medium. If the cells are efficiently distributed on the plate, it can be generally assumed that each cell will give rise to a single colony or Colony Forming Unit (CFU)."
    },
    {
      "topic": "Coulter and CASY counters",
      "quote_wikipedia": "A Coulter counter is an appliance that can count cells as well as measure their volume. It is based on the fact that cells show great electrical resistance; in other words, they conduct almost no electricity."
    },
    {
      "topic": "Flow cytometry",
      "quote_wikipedia": "Flow cytometry is by far the most sophisticated and expensive method for cell counting. In a flow cytometer the cells flow in a narrow stream in front of a laser beam."
    },
    {
      "topic": "Spectrophotometry and turbidometry",
      "quote_wikipedia": "Cell suspensions are turbid. Cells absorb and scatter the light. The higher the cell concentration, the higher the turbidity. Spectrophotometers can measure intensity of light very accurately."
    }
  ]
}
